"Если цена 4 000 тенге снижена на 50 %, то новая цена 3 000 тенге.": "Agar 4 000 tenge narx 50 % ga tushirilsa, yangi narx 3 000 tenge boʻladi.",
"S = M : m. Делитель вырос в 2 раза — частное уменьшилось в 2 раза.": "S = M : m. Boʻluvchi 2 marta oshdi — boʻlinma 2 marta kamaydi.",
