"Если цена остаётся прежней, а количество товара растёт, то стоимость…": "Agar narx oʻsha-oʻsha qolib, tovar miqdori oshsa, narxi…",
"Кошка у Аяна, поэтому у остальных детей в столбце «кошка» ставим «−».": "Mushuk Ayanda, shuning uchun qolgan bolalar uchun «mushuk» ustunida «−» qoʻyamiz.",
"Расстояние 200 м, скорость сближения 50 м/мин — догонит через 5 минут.": "Masofa 200 m, yaqinlashish tezligi 50 m/min — 5 daqiqadan keyin quvib yetadi.",
"Вопрос не высказывание: про него нельзя сказать «истинно» или «ложно».": "Savol mulohaza emas: u haqda «rost» yoki «yolgʻon» deb boʻlmaydi.",
