"В бочке 40 л воды. Взяли 3/8 воды. Сколько литров взяли?": "Bochkada 40 l suv bor. Suvning 3/8 qismi olindi. Necha litr olindi?",
"свободна четверть: 20 мест, занято 15; 40 мест, занято 30": "chorak qismi boʻsh: 20 ta oʻrin, 15 tasi band; 40 ta oʻrin, 30 tasi band",
