"При движении с отставанием расстояние между телами растёт.": "Orqada qolib harakatlanishda jismlar orasidagi masofa kattalashadi.",
"Клад не в первом и не во втором сундуке, значит, в третьем": "Xazina birinchi ham, ikkinchi ham sandiqda emas, demak, uchinchisida",
