"Время равно расстоянию, делённому на скорость: t = S : v сбл.": "Vaqt masofani tezlikka boʻlganga teng: t = S : v yaq.",
"Один всегда говорит правду, другой всегда лжёт. Кто есть кто?": "Biri doim rost gapiradi, ikkinchisi doim yolgʻon gapiradi. Kim kim?",
