"Сектор, который занимает 1/4 круга, равен двум секторам по 1/8.": "Doiraning 1/4 qismini egallagan sektor 1/8 dan ikkita sektorga teng.",
"Расстояние между ними не меняется — скорость сближения равна 0.": "Ular orasidagi masofa oʻzgarmaydi — yaqinlashish tezligi 0 ga teng.",
"Скорость сближения: 90 − 75 = 15 км/ч. Время: 60 : 15 = 4 часа.": "Yaqinlashish tezligi: 90 − 75 = 15 km/soat. Vaqt: 60 : 15 = 4 soat.",
