"Точка, лежащая от центра дальше радиуса, находится внутри круга.": "Markazdan radiusdan uzoqroqda joylashgan nuqta doira ichida boʻladi.",
"В противоположные стороны скорости складываем: 12 + 18 = 30 км/ч.": "Qarama-qarshi tomonlarga ketganda tezliklarni qoʻshamiz: 12 + 18 = 30 km/soat.",
